SQL:
SELECT *
FROM employees
WHERE reportsTo IS NULL;

SELECT SUM(amount) AS total_July_2004_payments
FROM payments
WHERE paymentDate BETWEEN '2004-07-01' AND '2004-07-31';

SELECT c.customername, CONCAT(e.firstname, ' ', e.lastname) AS 'Account Representative'
FROM customers c
JOIN employees e ON c.salesrepemployeenumber = e.employeenumber;

SELECT *
FROM products
WHERE productName LIKE '%Ford%';

SELECT *
FROM products
WHERE productName LIKE '%ship';

SELECT COUNT(*) AS number_of_customers
FROM customers
WHERE country IN ('Denmark', 'Norway', 'Sweden');

SELECT *
FROM customers
WHERE customerName REGEXP '[0-9]';

SELECT *
FROM employees
WHERE firstName IN ('Dianne', 'Diane');

SELECT *
FROM products
WHERE productName REGEXP ('ship'|'boat');

SELECT *
FROM products
WHERE productCode LIKE 'S700%';

SELECT *
FROM employees
WHERE CONCAT(firstname, ' ', lastname) REGEXP '[0-9%@]';

SELECT *
FROM products
WHERE productVendor LIKE '%Diecast';

SELECT *
FROM offices
ORDER BY country , state , city;

SELECT productLine AS 'Cars'
FROM productlines
WHERE productLine LIKE '%Cars%';

SELECT SUM(amount) AS 'Amount for 28th oct 2004'
FROM payments
WHERE paymentDate = '2004-10-28';

SELECT productName, productLine
FROM products
ORDER BY productLine;

SELECT amount
FROM payments
WHERE amount > 2 * (
	SELECT AVG(amount)
	FROM payments
);

SELECT customerName, city
FROM customers
WHERE salesRepEmployeeNumber IS NULL;

SELECT CONCAT(firstName, ' ', lastName) AS full_name
FROM employees
WHERE jobTitle LIKE '%VP%' OR jobTitle LIKE '%Manager%';
